def compute_netmf(A_lcc, window=10):
    P = embcom_utils.to_trans_mat(A_lcc); P_d = P.toarray()
    Ppow = sum(Pt for Pt in [P_d**i for i in 1..window]) / window
    M_raw = Ppow @ diag(vol / d); return log(max(M_raw, 1e-300))

def embed_svd(M, dim=64, clip=None):
    if clip is not None: M = max(M, clip)
    return TruncatedSVD(n_components=dim).fit_transform(M)
